package org.friendassessment.ambulance; public class App { public static void main(String[] args){ EmergencyDispatcher d=new EmergencyDispatcher(); d.addAmbulance(new Ambulance("F-ICU-1",AmbulanceCategory.ICU,"Karthik","Central")); EmergencyCase c=new EmergencyCase("F-E1","P1","Cardiac Emergency",PriorityLevel.CRITICAL,"Central","General Hospital",12); d.createEmergency(c); System.out.println("Assigned: "+c.ambulanceId()+", ETA: "+c.etaMinutes()); } }
